const crypto = require('crypto');
const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function b58encode(buf){
  let n = 0n;
  for (const b of buf) n = n*256n + BigInt(b);
  let s = '';
  if (n === 0n) s = '';
  while (n > 0n){ s = AL[Number(n % 58n)] + s; n /= 58n; }
  let z = 0; while (z < buf.length && buf[z] === 0) z++;
  return '1'.repeat(z) + (buf.length===0 ? '' : (s===''? '' : s));
}
function b58decode(str){
  // python base58 strips whitespace? handle plain
  let n = 0n;
  for (const ch of str){ const i = AL.indexOf(ch); if (i<0) throw new Error('bad char '+ch); n = n*58n + BigInt(i); }
  let bytes = [];
  while (n > 0n){ bytes.unshift(Number(n % 256n)); n /= 256n; }
  let z = 0; while (z < str.length && str[z] === '1') z++;
  return Buffer.concat([Buffer.alloc(z), Buffer.from(bytes)]);
}
function sha256(b){ return crypto.createHash('sha256').update(b).digest(); }
function checksum(b){ return sha256(sha256(b)).subarray(0,4); }
function b58encode_check(buf){ return b58encode(Buffer.concat([buf, checksum(buf)])); }
function b58decode_check(s){
  const full = b58decode(s);
  const payload = full.subarray(0, full.length-4);
  const ck = full.subarray(full.length-4);
  if (!ck.equals(checksum(payload))) throw new Error('Invalid checksum');
  return payload;
}
function pyRepr(buf){
  let out = "b'";
  for (const c of buf){
    if (c === 0x5c) out += '\\\\';
    else if (c === 0x27) out += "\\'";
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c === 0x09) out += '\\t';
    else if (c >= 0x20 && c <= 0x7e) out += String.fromCharCode(c);
    else out += '\\x' + c.toString(16).padStart(2,'0');
  }
  return out + "'";
}
module.exports = {AL,b58encode,b58decode,sha256,checksum,b58encode_check,b58decode_check,pyRepr};
